WHERE p.deleted_at IS NULL

  AND p.status = #{s.status}


  AND p.category_id = #{s.categoryId}


  AND p.sub_category_id = #{s.subCategoryId}


  AND (LOWER(p.title) LIKE LOWER(CONCAT('%', #{s.keyword}, '%'))
       OR LOWER(COALESCE(p.summary, '')) LIKE LOWER(CONCAT('%', #{s.keyword}, '%'))
       OR LOWER(COALESCE(u.name, '')) LIKE LOWER(CONCAT('%', #{s.keyword}, '%'))
       OR LOWER(COALESCE(u.login_id, '')) LIKE LOWER(CONCAT('%', #{s.keyword}, '%')))


  AND p.author_id = #{s.authorId}

